import Foundation
import SwiftData

/// Screenshot-only demo data, never shipped in a real build's data path — gated by an
/// environment variable set only when launching for App Store screenshot capture.
/// Seeds a handful of realistic-looking entries so list/detail/map screens look populated.
enum ScreenshotSeedData {
    static var isScreenshotMode: Bool {
        ProcessInfo.processInfo.environment["VANTAGE_SCREENSHOT_MODE"] == "1"
    }

    @MainActor
    static func seedIfNeeded(context: ModelContext) {
        guard isScreenshotMode else { return }
        let descriptor = FetchDescriptor<LocationEntryModel>()
        guard let existing = try? context.fetch(descriptor), existing.isEmpty else { return }

        let mountainData = Data(base64Encoded: mountainB64)
        let lighthouseData = Data(base64Encoded: lighthouseB64)
        let forestData = Data(base64Encoded: forestB64)
        let skylineData = Data(base64Encoded: skylineB64)

        let entries: [(LocationEntryModel, Data?)] = [
            (LocationEntryModel(
                timestamp: Date().addingTimeInterval(-3600 * 5),
                latitude: 41.0721, longitude: -71.8562,
                headingDegrees: 285,
                title: "Montauk Point Overlook",
                note: "Classic lighthouse shot from the bluff trail. Arrive before sunset traffic backs up the lot.",
                weatherSummary: "Clear, 62\u{00B0}F",
                tags: ["Golden Hour", "Landscape", "Coast"],
                shotList: [
                    ShotListItem(text: "Wide shot with bridge arc", isDone: true),
                    ShotListItem(text: "Long exposure, waves", isDone: false),
                    ShotListItem(text: "Drone establishing shot", isDone: false)
                ]
            ), mountainData),
            (LocationEntryModel(
                timestamp: Date().addingTimeInterval(-3600 * 30),
                latitude: 41.9480, longitude: -70.6190,
                headingDegrees: 95,
                title: "Nobska Point Lighthouse",
                note: "Best light right after sunrise. Small lot fills up fast in summer.",
                weatherSummary: "Partly Cloudy, 58\u{00B0}F",
                tags: ["Sunrise", "Architecture"],
                parkingNotes: "Small lot on Church St, free before 8am",
                shotList: [
                    ShotListItem(text: "Lighthouse + foreground rocks", isDone: false),
                    ShotListItem(text: "Detail shot of lantern room", isDone: false)
                ]
            ), lighthouseData),
            (LocationEntryModel(
                timestamp: Date().addingTimeInterval(-3600 * 55),
                latitude: 44.2619, longitude: -71.3033,
                headingDegrees: 40,
                title: "Franconia Ridge Trailhead",
                note: "Foliage peak expected in ~2 weeks. Bring the 70-200 for compression shots.",
                tags: ["Hiking", "Fall Foliage", "Landscape"],
                shotList: [
                    ShotListItem(text: "Ridge line panorama", isDone: false)
                ]
            ), forestData),
            (LocationEntryModel(
                timestamp: Date().addingTimeInterval(-3600 * 80),
                latitude: 40.7484, longitude: -73.9857,
                headingDegrees: 310,
                title: "Rooftop on 5th",
                note: "Client wants skyline behind the couple during blue hour.",
                weatherSummary: "Clear, 71\u{00B0}F",
                tags: ["Blue Hour", "Client Shoot", "Urban"],
                parkingNotes: "Street parking impossible, use garage on 34th",
                shotList: [
                    ShotListItem(text: "Couple portraits, skyline background", isDone: true),
                    ShotListItem(text: "Wide establishing shot", isDone: true),
                    ShotListItem(text: "Detail shots, rings", isDone: false)
                ]
            ), skylineData)
        ]

        for (entry, imageData) in entries {
            context.insert(entry)
            if let imageData {
                let asset = PhotoAsset(imageData: imageData, isReference: true, entry: entry)
                context.insert(asset)
            }
        }
        try? context.save()
    }
}

private let mountainB64 = ""
private let lighthouseB64 = ""
private let forestB64 = ""
private let skylineB64 = ""
